using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ReductionCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Any/ReductionCustomDescription", order = 0)]
public class ReductionCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		ReductionAction reductionAction = battleAction as ReductionAction;
		string text = "";
		string localizedString = base.localizationManager.GetLocalizedString("AmountOfCorruptionDecreased");
		if (reductionAction.UseOnEnemiesAndCompanions)
		{
			string arg = Smart.Format(base.localizationManager.GetLocalizedString("DealXPurificationOwnerOfTheDie"), reductionAction.PurificationMultiplier);
			text = "\n" + Smart.Format(base.localizationManager.GetLocalizedForEach(), arg, localizedString);
		}
		else
		{
			text = "\n" + Smart.Format(base.localizationManager.GetLocalizedForEach(), reductionAction.PurifyAction.GetActionDescription(reductionAction.PurificationMultiplier).UppercaseFirst().RemoveLastIfDotOrCommaAndIfNotJapaneseNorKoreanNorTraditionalChinese(), localizedString);
		}
		if (amountModified == EffectsValues.NO_VALUE_STRING)
		{
			return Smart.Format(GetRawLocalizedDescription(battleAction), reductionAction.FinalValue) + text;
		}
		return Smart.Format(GetRawLocalizedDescription(battleAction), GetFinalAmountWithoutEquation(amountModified), reductionAction.FinalValue) + text;
	}
}
